rning":{"screen":"driver","keys":["driver_addition_notice","driver_addition_invoice_notice"],"styleOnly":true},"cashier_customer_edit":{"screen":"cashier","keys":["cashier_customer_edit"],"styleOnly":true},"assembly_order_components":{"screen":"assembly","keys":["assembly_stage_action","assembly_stage_state","assembly_order_age","assembly_order_note"],"styleOnly":true},"burger_order_components":{"screen":"burger_kitchen","keys":["burger_stage_action","burger_stage_state","burger_required_note","burger_confirm_note"],"styleOnly":true},"cashier_burger_components":{"screen":"cashier","keys":["cashier_burger_skip","cashier_burger_state","cashier_burger_timer"],"styleOnly":true},"assembly_burger_components":{"screen":"assembly","keys":["assembly_burger_skip","assembly_burger_state","assembly_burger_timer"],"styleOnly":true},"staff_dynamic_fields":{"screen":"staff","keys":["staff_assembly_branch","staff_assembly_target","staff_access_role","staff_access_branch","staff_permission_value"],"styleOnly":true},"system_qa_fields":{"screen":"system","keys":["system_qa_result","system_qa_note"],"styleOnly":true},"finance_evidence_fields":{"screen":"finance","keys":["finance_fee_amount","finance_fee_reference"],"styleOnly":true},"finance_evidence_controls":{"screen":"finance","keys":["finance_fee_save","finance_fee_status","finance_fee_history"],"styleOnly":true},"dashboard_lifecycle_fields":{"screen":"dashboard","keys":["lifecycle_invoice","lifecycle_reoffer_driver","lifecycle_reoffer_reason"],"styleOnly":true},"dashboard_lifecycle_status":{"screen":"dashboard","keys":["lifecycle_countdown","lifecycle_state"],"styleOnly":true},"dashboard_follow_control":{"screen":"dashboard","keys":["dashboard_order_follow"],"styleOnly":true},"system_theme_controls":{"screen":"system","keys":["system_theme_choice"],"styleOnly":true},"cashier_cancellation_controls":{"screen":"cashier","keys":["cashier_cancel_ack","cashier_cancel_banner","cashier_cancel_note"],"styleOnly":true},"driver_feedback_controls":{"screen":"driver","keys":["driver_feedback_refresh","driver_feedback_open"],"styleOnly":true},"driver_rating_fields":{"screen":"driver","keys":["driver_rating_note"],"styleOnly":true},"driver_rating_controls":{"screen":"driver","keys":["driver_rating_star","driver_rating_submit","driver_rating_close"],"styleOnly":true},"driver_grievance_fields":{"screen":"driver","keys":["driver_grievance_kind","driver_grievance_details"],"styleOnly":true},"driver_grievance_controls":{"screen":"driver","keys":["driver_grievance_save","driver_grievance_close"],"styleOnly":true}}'::jsonb;
BEGIN
 IF v IS NULL OR jsonb_typeof(v)<>'object' THEN RETURN false; END IF;
 FOR g IN SELECT * FROM jsonb_each(v) LOOP
  IF NOT spec ? g.key OR (p_screen<>'all' AND spec->g.key->>'screen'<>p_screen) OR jsonb_typeof(g.value)<>'array' THEN RETURN false; END IF;
  SELECT array_agg(k) INTO allowed FROM jsonb_array_elements_text(spec->g.key->'keys') k;
  IF jsonb_array_length(g.value)<>cardinality(allowed) THEN RETURN false; END IF;
  IF coalesce((spec->g.key->>'styleOnly')::boolean,false) AND (SELECT array_agg(a.row->>'key' ORDER BY a.ord) FROM jsonb_array_elements(g.value) WITH ORDINALITY a(row,ord)) IS DISTINCT FROM allowed THEN RETURN false; END IF;
  IF (SELECT count(*) FROM jsonb_array_elements(g.value) a WHERE a->>'orderMode'='inherit') NOT IN (0,cardinality(allowed)) THEN RETURN false; END IF;
  seen:='{}';
  FOR e IN SELECT * FROM jsonb_array_elements(g.value) LOOP
   IF jsonb_typeof(e)<>'object' THEN RETURN false; END IF;
   IF NOT (e ?& ARRAY['key','shape','size']) OR EXISTS(SELECT 1 FROM jsonb_object_keys(e) k WHERE k NOT IN ('key','shape','size','font','weight','spacing','border','shadow','tone','orderMode','icon','hover','press','align','textScale','spaceBlock','outerGap','placement'))
      OR NOT coalesce(e->>'key'=ANY(allowed),false) OR coalesce(e->>'key'=ANY(seen),true)
      OR NOT coalesce(e->>'shape' IN ('inherit','pack','square','round','pill','outline','icon_label'),false)
      OR NOT coalesce(e->>'size' IN ('inherit','normal','large'),false) THEN RETURN false;END IF;
   IF EXISTS(SELECT 1 FROM jsonb_each(e) x WHERE x.key NOT IN ('key','shape','size') AND NOT CASE x.key
      WHEN 'orderMode' THEN x.value='"inherit"'::jsonb
      WHEN 'font' THEN x.value IN ('"system"'::jsonb,'"tahoma"'::jsonb,'"serif"'::jsonb,'"cairo"'::jsonb,'"noto"'::jsonb)
      WHEN 'align' THEN x.value IN ('"start"'::jsonb,'"center"'::jsonb,'"end"'::jsonb)
      WHEN 'textScale' THEN x.value IN ('"normal"'::jsonb,'"large"'::jsonb)
      WHEN 'weight' THEN x.value IN ('"normal"'::jsonb,'"strong"'::jsonb)
      WHEN 'spacing' THEN x.value IN ('"normal"'::jsonb,'"wide"'::jsonb)
      WHEN 'spaceBlock' THEN x.value IN ('"normal"'::jsonb,'"wide"'::jsonb)
      WHEN 'outerGap' THEN x.value IN ('"normal"'::jsonb,'"wide"'::jsonb)
      WHEN 'placement' THEN x.value IN ('"start"'::jsonb,'"center"'::jsonb,'"end"'::jsonb) AND e->>'key' IN ('ffx-kpis','ffx-shortcuts','ffx-order-list','ffx-overdue','ff76Body','ff51CustomersList','ff51CustomerHistory','ff51CustomerNotesList','ff51ArchiveList','ff51RatingsList','ff51CatalogItems','ff51OffersList','ff49ReservationsList','ff41CaseList','ff39InboxList')
      WHEN 'border' THEN x.value IN ('"thin"'::jsonb,'"strong"'::jsonb)
      WHEN 'shadow' THEN x.value IN ('"none"'::jsonb,'"soft"'::jsonb)
      WHEN 'icon' THEN x.value IN ('"none"'::jsonb,'"check"'::jsonb,'"arrow"'::jsonb,'"star"'::jsonb,'"search"'::jsonb,'"file"'::jsonb) AND e->>'key' IN ('ff76Run','ff76Preview','ff76Download','ff76Share','ffx-hero-new','ffx-hero-reserve','ff51ArchiveRefresh','ff51ArchiveExport','ff51CustomerFind')
      WHEN 'hover' THEN x.value IN ('"none"'::jsonb,'"outline"'::jsonb,'"shadow"'::jsonb) AND e->>'key' IN ('ff76Run','ff76Preview','ff76Download','ff76Share','ffx-hero-new','ffx-hero-reserve','ff51ArchiveRefresh','ff51ArchiveExport','ff51CustomerFind')
      WHEN 'press' THEN x.value IN ('"none"'::jsonb,'"inset"'::jsonb) AND e->>'key' IN ('ff76Run','ff76Preview','ff76Download','ff76Share','ffx-hero-new','ffx-hero-reserve','ff51ArchiveRefresh','ff51ArchiveExport','ff51CustomerFind')
      WHEN 'tone' THEN x.value IN ('"navy"'::jsonb,'"red"'::jsonb,'"light"'::jsonb,'"dark"'::jsonb) AND e->>'key' IN ('ff76Run','ff76Preview','ff76Download','ff76Share','ffx-hero-new','ffx-hero-reserve','ff51ArchiveRefresh','ff51ArchiveExport','ff51CustomerFind','newBranch','newPhone','newArea','newFee','newNotes','newCustomerName','newChannel','newFullAddress','ffbMenuSearch','ffbQuickInput','newItems','orderSearch','orderBranchFilter','orderStatusFilter','ff51CustomerSearch','ff51CustomerNoteText','ff76From','ff76To','ff76Branch','ff76Driver','ffA10Staff','ffA10Area','ffA10Item','ffA10Status','ff76Mode','ff76Trend','ff51ArchiveFrom','ff51ArchiveTo','ff51ArchiveStatus','ff51ArchiveBranch','ffA05StaffSearch','ffA05StaffRole','ffA05StaffActive','ffA05StaffSort','ff49ReserveName','ff49ReservePhone','ff49ReserveNotes','ff49ReservePickup','ff49ReserveItems','ff41Subject','ff41Description','ff39Title','ff39Body','ffx-branch','ff2-search','ff40From','ff40To','ff40ReportBranch')
      ELSE false END) THEN RETURN false; END IF;
   seen:=array_append(seen,e->>'key');
  END LOOP;
 END LOOP;
 RETURN true;
END $function$;
